const { withAppBuildGradle, withGradleProperties } = require('expo/config-plugins');

// android/ is generated by `expo prebuild`, so anything the release build depends on
// is declared here instead of edited by hand.
const GRADLE_PROPERTIES = {
  // Compressed .so files: a smaller APK to sideload, extracted once at install.
  'expo.useLegacyPackaging': 'true',
  'org.gradle.jvmargs': '-Xmx4g -XX:MaxMetaspaceSize=1g',
};

// Keystore path, passwords and alias live in ~/.gradle/gradle.properties, never in
// this repo. Without them a release build falls back to the debug key, which
// scripts/build-apk.sh refuses to ship.
const STORE_FILE_PROPERTY = 'FEEDLINE_RELEASE_STORE_FILE';

const RELEASE_SIGNING_CONFIG = `
        release {
            if (project.hasProperty('${STORE_FILE_PROPERTY}')) {
                storeFile file(project.property('${STORE_FILE_PROPERTY}'))
                storePassword project.property('FEEDLINE_RELEASE_STORE_PASSWORD')
                keyAlias project.property('FEEDLINE_RELEASE_KEY_ALIAS')
                keyPassword project.property('FEEDLINE_RELEASE_KEY_PASSWORD')
            }
        }
`;

// The stock template's release buildType line, anchored on its comment so the debug
// buildType (same signingConfig) is left alone.
const TEMPLATE_RELEASE_SIGNING =
  /\n(\s*)\/\/ Caution! In production[^\n]*\n\s*\/\/ see https:\/\/reactnative\.dev\/docs\/signed-apk-android\.\n\s*signingConfig signingConfigs\.debug/;
const SIGNING_CONFIGS_OPEN = /(\n\s*signingConfigs\s*\{\n)/;

function withReleaseSigningConfig(config) {
  return withAppBuildGradle(config, (cfg) => {
    let contents = cfg.modResults.contents;
    if (contents.includes(STORE_FILE_PROPERTY)) return cfg;
    if (!SIGNING_CONFIGS_OPEN.test(contents) || !TEMPLATE_RELEASE_SIGNING.test(contents)) {
      // Silently continuing would sign releases with the shared debug key.
      throw new Error(
        'withReleaseSigning: app/build.gradle no longer matches the Expo template; update the anchors.',
      );
    }
    contents = contents.replace(SIGNING_CONFIGS_OPEN, `$1${RELEASE_SIGNING_CONFIG}`);
    contents = contents.replace(
      TEMPLATE_RELEASE_SIGNING,
      (_match, indent) =>
        `\n${indent}// Release key when configured, else debug so \`expo run:android\` still works.\n` +
        `${indent}signingConfig(project.hasProperty('${STORE_FILE_PROPERTY}') ? signingConfigs.release : signingConfigs.debug)`,
    );
    cfg.modResults.contents = contents;
    return cfg;
  });
}

function withPinnedGradleProperties(config) {
  return withGradleProperties(config, (cfg) => {
    const managed = new Set(Object.keys(GRADLE_PROPERTIES));
    const kept = cfg.modResults.filter((item) => !(item.type === 'property' && managed.has(item.key)));
    while (kept.length > 0 && kept[kept.length - 1].type === 'empty') kept.pop();
    cfg.modResults = [
      ...kept,
      ...Object.entries(GRADLE_PROPERTIES).map(([key, value]) => ({ type: 'property', key, value })),
      { type: 'empty' },
    ];
    return cfg;
  });
}

module.exports = function withReleaseSigning(config) {
  return withPinnedGradleProperties(withReleaseSigningConfig(config));
};
